"""Create isolated Stock V6 Phase 1 broad-universe research panel.

V6 is a new research track. Frozen V5, V4 paper trading, dashboard runtime,
crypto research, and brokerage settings are not modified.
"""

from pathlib import Path


ROOT = Path("ml/v6")
INIT = ROOT / "__init__.py"
CONFIG = ROOT / "config.py"
PHASE1 = ROOT / "phase1.py"


def main():
    ROOT.mkdir(parents=True, exist_ok=True)

    INIT.write_text(
        '"""Stock V6 broad-universe research track."""\n\nRESEARCH_VERSION = "v6"\n',
        encoding="utf-8",
    )
    print("[APPLY] ml/v6/__init__.py")

    CONFIG.write_text(
        '''"""Stock V6 Phase 1 research contract."""\n\nfrom pathlib import Path\n\nRESEARCH_VERSION = "v6"\nBENCHMARK_SYMBOL = "SPY"\nPRIMARY_HORIZON_DAYS = 5\nTOP_COUNT = 5\nPURGE_GAP_TRADING_SESSIONS = 5\n\nFEATURE_ROOT = Path("data/features/stocks")\nOUTPUT_ROOT = Path("data/model/v6/phase1")\nPANEL_PATH = OUTPUT_ROOT / "research_panel.parquet"\nMANIFEST_PATH = OUTPUT_ROOT / "manifest.json"\n\nFEATURE_COLUMNS = (\n    "daily_return",\n    "return_2d",\n    "return_3d",\n    "return_5d",\n    "return_10d",\n    "return_20d",\n    "return_60d",\n    "price_vs_sma_7",\n    "price_vs_sma_20",\n    "price_vs_sma_50",\n    "price_vs_sma_200",\n    "sma_7_vs_sma_20",\n    "sma_20_vs_sma_50",\n    "sma_50_vs_sma_200",\n    "intraday_range",\n    "open_close_range",\n    "volume_ratio",\n    "volume_change_5d",\n    "volatility_5d",\n    "volatility_20d",\n    "volatility_ratio_5_20",\n    "trend_20_50",\n    "trend_50_200",\n    "distance_from_20d_high",\n    "distance_from_20d_low",\n    "rsi_centered",\n)\n''',
        encoding="utf-8",
    )
    print("[APPLY] ml/v6/config.py")

    PHASE1.write_text(
        '''"""Stock V6 Phase 1: 100-stock + SPY all-history integrity panel.\n\nPurpose\n-------\nBuild and audit the full 100-stock candidate universe with SPY as benchmark\ncontext. Phase 1 performs no model fitting, no threshold selection, no\nportfolio simulation, no candidate freeze, no holdout scoring, and no orders.\n\nTarget\n------\nPrimary target is the candidate's forward 5-trading-session return minus SPY's\nforward 5-trading-session return over the exact same endpoint. SPY is never an\ninvestable Top-5 candidate.\n\nResearch safety\n---------------\nFrozen V5 and V4 are controls and are not modified. Existing paper portfolio\nstate and journals are not modified. Crypto tracks are not modified.\n"""\n\nfrom __future__ import annotations\n\nimport json\nimport sys\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\n\nPROJECT_ROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(PROJECT_ROOT / "data-ingestion"))\n\nfrom v5_symbols import V5_BENCHMARK_SYMBOL, V5_SYMBOLS, get_v5_sector  # noqa: E402\nfrom ml.v6.config import (  # noqa: E402\n    BENCHMARK_SYMBOL,\n    FEATURE_COLUMNS,\n    FEATURE_ROOT,\n    MANIFEST_PATH,\n    OUTPUT_ROOT,\n    PANEL_PATH,\n    PRIMARY_HORIZON_DAYS,\n    PURGE_GAP_TRADING_SESSIONS,\n)\n\n\ndef feature_path(symbol: str) -> Path:\n    return FEATURE_ROOT / symbol / f"{symbol}_features.parquet"\n\n\ndef load_symbol(symbol: str) -> pd.DataFrame:\n    path = feature_path(symbol)\n    if not path.exists():\n        raise FileNotFoundError(f"Missing feature history: {path}")\n\n    columns = [\n        "timestamp_utc",\n        "open",\n        "close",\n        *FEATURE_COLUMNS,\n    ]\n    frame = pd.read_parquet(path, columns=columns).copy()\n    frame["timestamp_utc"] = pd.to_datetime(frame["timestamp_utc"], utc=True)\n    frame = frame.sort_values("timestamp_utc").reset_index(drop=True)\n\n    if frame["timestamp_utc"].duplicated().any():\n        raise ValueError(f"Duplicate timestamps in {symbol}")\n\n    return frame\n\n\ndef add_forward_leg(frame: pd.DataFrame, prefix: str) -> pd.DataFrame:\n    h = PRIMARY_HORIZON_DAYS\n    out = frame.copy()\n    out[f"{prefix}_target_endpoint_utc"] = out["timestamp_utc"].shift(-h)\n    out[f"forward_{prefix}_return_{h}d"] = out["close"].shift(-h) / out["close"] - 1.0\n    return out\n\n\ndef main():\n    if BENCHMARK_SYMBOL != V5_BENCHMARK_SYMBOL:\n        raise RuntimeError("V6 benchmark contract disagrees with configured stock universe")\n    if len(V5_SYMBOLS) != 100 or len(set(V5_SYMBOLS)) != 100:\n        raise RuntimeError(f"Expected exactly 100 unique candidates, found {len(set(V5_SYMBOLS))}")\n    if BENCHMARK_SYMBOL in V5_SYMBOLS:\n        raise RuntimeError("SPY must remain outside the investable candidate universe")\n\n    all_symbols = [*V5_SYMBOLS, BENCHMARK_SYMBOL]\n    missing = [s for s in all_symbols if not feature_path(s).exists()]\n    if missing:\n        raise FileNotFoundError("Missing V6 feature histories: " + ", ".join(missing))\n\n    raw = {symbol: load_symbol(symbol) for symbol in all_symbols}\n\n    coverage = []\n    for symbol, frame in raw.items():\n        coverage.append({\n            "symbol": symbol,\n            "rows": int(len(frame)),\n            "start_utc": frame["timestamp_utc"].min().isoformat(),\n            "end_utc": frame["timestamp_utc"].max().isoformat(),\n            "feature_complete_rows": int(frame[list(FEATURE_COLUMNS)].notna().all(axis=1).sum()),\n        })\n\n    shared_dates = set(raw[BENCHMARK_SYMBOL]["timestamp_utc"].tolist())\n    for symbol in V5_SYMBOLS:\n        shared_dates &= set(raw[symbol]["timestamp_utc"].tolist())\n    shared_dates = sorted(shared_dates)\n    if not shared_dates:\n        raise RuntimeError("No common timestamps across all 100 candidates plus SPY")\n\n    benchmark = add_forward_leg(raw[BENCHMARK_SYMBOL][["timestamp_utc", "close"]], "spy")\n    benchmark = benchmark.rename(columns={"close": "spy_close"})\n\n    frames = []\n    h = PRIMARY_HORIZON_DAYS\n    for symbol in V5_SYMBOLS:\n        frame = raw[symbol].copy()\n        frame.insert(0, "symbol", symbol)\n        frame.insert(1, "sector", get_v5_sector(symbol))\n        frame["feature_complete"] = frame[list(FEATURE_COLUMNS)].notna().all(axis=1)\n        frame = add_forward_leg(frame, "stock")\n        frame = frame.merge(benchmark, on="timestamp_utc", how="inner", validate="one_to_one")\n\n        endpoint_match = frame["stock_target_endpoint_utc"].eq(frame["spy_target_endpoint_utc"])\n        frame["endpoint_matches_spy"] = endpoint_match\n        frame["is_labeled"] = (\n            endpoint_match\n            & frame[f"forward_stock_return_{h}d"].notna()\n            & frame[f"forward_spy_return_{h}d"].notna()\n        )\n        frame[f"forward_relative_return_{h}d"] = (\n            frame[f"forward_stock_return_{h}d"]\n            - frame[f"forward_spy_return_{h}d"]\n        ).where(frame["is_labeled"])\n        frames.append(frame)\n\n    panel = pd.concat(frames, ignore_index=True)\n    panel = panel[panel["timestamp_utc"].isin(shared_dates)].copy()\n    panel = panel.sort_values(["timestamp_utc", "symbol"]).reset_index(drop=True)\n\n    counts = panel.groupby("timestamp_utc")["symbol"].nunique()\n    if int(counts.min()) != 100 or int(counts.max()) != 100:\n        raise RuntimeError("V6 shared-date panel does not contain exactly 100 candidates per date")\n    if panel.duplicated(["timestamp_utc", "symbol"]).any():\n        raise RuntimeError("Duplicate timestamp/symbol rows in V6 panel")\n\n    target = f"forward_relative_return_{h}d"\n    panel["target_rank_pct"] = panel.groupby("timestamp_utc")[target].rank(\n        method="average", pct=True, ascending=True\n    )\n    panel["eligible_feature_count"] = panel.groupby("timestamp_utc")["feature_complete"].transform("sum")\n    panel["eligible_labeled_count"] = panel.groupby("timestamp_utc")["is_labeled"].transform("sum")\n    panel["fully_eligible"] = panel["feature_complete"] & panel["is_labeled"]\n\n    complete_by_date = panel.groupby("timestamp_utc")["feature_complete"].sum()\n    labeled_by_date = panel.groupby("timestamp_utc")["is_labeled"].sum()\n    fully_eligible_by_date = panel.groupby("timestamp_utc")["fully_eligible"].sum()\n\n    all_100_feature_complete_dates = complete_by_date[complete_by_date.eq(100)]\n    all_100_labeled_dates = labeled_by_date[labeled_by_date.eq(100)]\n    all_100_fully_eligible_dates = fully_eligible_by_date[fully_eligible_by_date.eq(100)]\n\n    finite_target = panel.loc[panel["is_labeled"], target].replace([np.inf, -np.inf], np.nan).dropna()\n\n    OUTPUT_ROOT.mkdir(parents=True, exist_ok=True)\n    panel.to_parquet(PANEL_PATH, index=False)\n\n    manifest = {\n        "research_version": "v6",\n        "phase": 1,\n        "generated_at_utc": datetime.now(timezone.utc).isoformat(),\n        "stage": "broad_universe_all_history_integrity_panel",\n        "candidate_count": 100,\n        "benchmark_symbol": BENCHMARK_SYMBOL,\n        "benchmark_is_investable": False,\n        "total_data_symbols": 101,\n        "feature_count": len(FEATURE_COLUMNS),\n        "feature_columns": list(FEATURE_COLUMNS),\n        "primary_horizon_days": h,\n        "primary_target": target,\n        "purge_gap_trading_sessions_for_future_modeling": PURGE_GAP_TRADING_SESSIONS,\n        "panel_rows": int(len(panel)),\n        "shared_trading_dates": int(panel["timestamp_utc"].nunique()),\n        "date_range": {\n            "start": panel["timestamp_utc"].min().isoformat(),\n            "end": panel["timestamp_utc"].max().isoformat(),\n        },\n        "full_cross_section": {\n            "minimum_candidates_per_date": int(counts.min()),\n            "maximum_candidates_per_date": int(counts.max()),\n            "all_dates_have_100_candidates": bool(counts.eq(100).all()),\n        },\n        "feature_completeness": {\n            "all_100_complete_date_count": int(len(all_100_feature_complete_dates)),\n            "first_all_100_complete_date": (\n                all_100_feature_complete_dates.index.min().isoformat()\n                if len(all_100_feature_complete_dates) else None\n            ),\n            "last_all_100_complete_date": (\n                all_100_feature_complete_dates.index.max().isoformat()\n                if len(all_100_feature_complete_dates) else None\n            ),\n        },\n        "label_completeness": {\n            "all_100_labeled_date_count": int(len(all_100_labeled_dates)),\n            "first_all_100_labeled_date": (\n                all_100_labeled_dates.index.min().isoformat()\n                if len(all_100_labeled_dates) else None\n            ),\n            "last_all_100_labeled_date": (\n                all_100_labeled_dates.index.max().isoformat()\n                if len(all_100_labeled_dates) else None\n            ),\n        },\n        "fully_eligible_cross_section": {\n            "all_100_eligible_date_count": int(len(all_100_fully_eligible_dates)),\n            "first_all_100_eligible_date": (\n                all_100_fully_eligible_dates.index.min().isoformat()\n                if len(all_100_fully_eligible_dates) else None\n            ),\n            "last_all_100_eligible_date": (\n                all_100_fully_eligible_dates.index.max().isoformat()\n                if len(all_100_fully_eligible_dates) else None\n            ),\n        },\n        "target_summary": {\n            "count": int(len(finite_target)),\n            "mean": float(finite_target.mean()),\n            "median": float(finite_target.median()),\n            "std": float(finite_target.std()),\n            "positive_fraction": float((finite_target > 0).mean()),\n        },\n        "coverage": coverage,\n        "known_limitations": [\n            "Present-day 100-stock universe introduces survivorship bias; point-in-time historical membership is not yet available.",\n            "Phase 1 does not score a holdout or select a model.",\n        ],\n        "research_safety": {\n            "v4_modified": False,\n            "v5_modified": False,\n            "paper_portfolio_modified": False,\n            "paper_journal_modified": False,\n            "crypto_tracks_modified": False,\n            "model_fitting": False,\n            "portfolio_simulation": False,\n            "candidate_frozen": False,\n            "brokerage_orders": False,\n        },\n    }\n    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2), encoding="utf-8")\n\n    print("STOCK V6 PHASE 1")\n    print("=" * 88)\n    print(f"Candidates:                 {manifest['candidate_count']}")\n    print(f"Benchmark:                  {BENCHMARK_SYMBOL} (context only, not investable)")\n    print(f"Total data symbols:         {manifest['total_data_symbols']}")\n    print(f"Panel rows:                 {manifest['panel_rows']:,}")\n    print(f"Shared trading dates:       {manifest['shared_trading_dates']:,}")\n    print(f"Date range:                 {manifest['date_range']['start']} -> {manifest['date_range']['end']}")\n    print(f"Registered features:        {manifest['feature_count']}")\n    print(f"Primary target:             {target}")\n    print(f"100-feature-complete dates: {manifest['feature_completeness']['all_100_complete_date_count']:,}")\n    print(f"First fully complete date:  {manifest['feature_completeness']['first_all_100_complete_date']}")\n    print(f"100 fully eligible dates:   {manifest['fully_eligible_cross_section']['all_100_eligible_date_count']:,}")\n    print(f"First fully eligible date:  {manifest['fully_eligible_cross_section']['first_all_100_eligible_date']}")\n    print(f"Last fully eligible date:   {manifest['fully_eligible_cross_section']['last_all_100_eligible_date']}")\n    print(f"Target observations:        {manifest['target_summary']['count']:,}")\n    print(f"ALT/STOCK beats SPY:        {manifest['target_summary']['positive_fraction']:.2%}")\n    print()\n    print("Phase 1 only: no fitting, tuning, portfolio simulation, holdout scoring, freeze, or orders.")\n    print("Frozen V5, V4 paper trading, dashboard runtime, and crypto tracks were not modified.")\n\n\nif __name__ == "__main__":\n    main()\n''',
        encoding="utf-8",
    )
    print("[APPLY] ml/v6/phase1.py")

    print()
    print("Stock V6 Phase 1 broad-universe patch complete.")
    print("100 candidates + SPY benchmark; all-history integrity panel only.")
    print("No model fitting, portfolio simulation, holdout scoring, or brokerage orders.")


if __name__ == "__main__":
    main()
